use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::{BTreeMap,BTreeSet},fs,path::Path};
const R:&str="/tmp/zopro-single-epoch-advancer";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn add(p:impl AsRef<Path>,pins:&mut BTreeMap<String,String>){let p=p.as_ref();let h=hash(p);if let Some(old)=pins.insert(p.display().to_string(),h.clone()){assert_eq!(old,h)}}
fn prior()->BTreeSet<String>{let m=read("/tmp/zopro-pmu-c7a-20261027/context/manifest.json");let mut seen:BTreeSet<String>=serde_json::from_value(m["prior_proof_sha256"].clone()).unwrap();assert_eq!(seen.len(),12143);for(f,h)in read("/tmp/zopro-pmu-c7a-20261027/proof-inventory.json").as_object().unwrap(){assert_eq!(hash(f),h.as_str().unwrap());if f.ends_with(".proof"){assert_eq!(fs::metadata(f).unwrap().len(),164);assert!(seen.insert(h.as_str().unwrap().into()));}}assert_eq!(seen.len(),12173);seen}
fn prepare(){let r=Path::new(R);assert_eq!(read(r.join("native-qualified/result.json"))["status"],"complete");assert_eq!(read(r.join("native-qualified/candidate-core/tests.json"))["passed_tests"].as_array().unwrap().len(),119);
 let m=read("/tmp/zopro-clean-fft-adoption/production-source-manifest.json");let mut p=read("/tmp/zopro-g1-raw-scratch/perf-plan.json");p["blocks"]=json!(9);p["environment"]=m["environment"].clone();p["checks"]=json!([]);p["frequency_hz"]=json!(199);
 for c in p["cases"].as_array_mut().unwrap(){c["rounds"]=json!(if c["name"]=="1x2-w32"{151}else if c["name"]=="1x2-w16"{251}else{31});if c["shape"]=="merge-54x1"{c["profile_rounds"]=json!(17);}}
 let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("source-pins.json"))).unwrap();for(f,h)in &pins{assert_eq!(&hash(f),h)}
 let accepted=read("/tmp/zopro-clean-fft-leaves/native/candidate/artifacts.json");let candidate=read(r.join("native-qualified/candidate/artifacts.json"));
 let mut variants=Vec::new();for(name,a,mode)in [("accepted",&accepted,"0"),("off",&candidate,"0"),("on",&candidate,"1")]{assert_eq!(hash(a["binary"].as_str().unwrap()),a["binary_sha256"].as_str().unwrap());for(f,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(f),h.as_str().unwrap());add(f,&mut pins)}add(a["binary"].as_str().unwrap(),&mut pins);variants.push(json!({"name":name,"binary":a["binary"],"environment":{"ZOPRO_CPU_SINGLE_EPOCH_ADVANCER":mode}}));}
 p["variants"]=json!(variants);for c in p["cases"].as_array().unwrap(){add(c["image"].as_str().unwrap(),&mut pins);add(c["request"].as_str().unwrap(),&mut pins)}for(f,h)in p["pins"].as_object().unwrap(){if f.starts_with("/tmp/zopro-keys/"){assert_eq!(hash(f),h.as_str().unwrap());add(f,&mut pins)}}
 for f in ["prepare.rs","prepare-sdk.rs","prepare-sdk","analyze.rs","analyze","close.rs","close","stats.rs","design.md","test-repair.json","native-qualified/result.json","native-qualified/candidate/artifacts.json","native-qualified/candidate-core/tests.json","native-qualified/candidate-prover/tests.json"]{add(r.join(f),&mut pins)}
 for f in ["/usr/bin/perf","/tmp/zopro-xtask-fast-screen-target/release/xtask","/tmp/zopro-gnark-verify/verify","/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"]{add(f,&mut pins)}
 let mut transitive=BTreeMap::new();for line in fs::read_to_string(r.join("native-qualified/candidate-libraries/stdout.log")).unwrap().lines(){let v:Value=match serde_json::from_str(line){Ok(v)=>v,Err(_)=>continue};let name=v["target"]["name"].as_str().unwrap_or("");if v["reason"]=="compiler-artifact"&&["crossbeam_epoch","crossbeam_deque","crossbeam_utils","rayon_core"].contains(&name){let paths:Vec<_>=v["filenames"].as_array().unwrap().iter().filter_map(Value::as_str).filter(|p|p.ends_with(".rlib")).collect();assert_eq!(paths.len(),1);let path=paths[0];add(path,&mut pins);assert!(transitive.insert(name.to_owned(),json!({"path":path,"sha256":hash(path),"features":v["features"]})).is_none());}}assert_eq!(transitive.len(),4);save(r.join("transitive-libraries.json"),&json!(transitive));add(r.join("transitive-libraries.json"),&mut pins);
 p["pins"]=json!(pins);p["prior_proof_sha256"]=json!(prior());save(r.join("perf-before-preflight.json"),&p);
 let mut steps=Vec::new();let mut jobs=Vec::new();for mode in ["off","on"]{for c in p["cases"].as_array().unwrap().iter().filter(|c|c["workers"]==32){let name=format!("{mode}-{}-w4",c["shape"].as_str().unwrap());let dir=r.join("preflight-proofs").join(&name).join(Path::new(c["image"].as_str().unwrap()).file_stem().unwrap());let mut env=p["environment"].clone();env["RAYON_NUM_THREADS"]=json!("4");env["ZOPRO_CPU_SINGLE_EPOCH_ADVANCER"]=json!(if mode=="on"{"1"}else{"0"});steps.push(json!({"kind":"command","name":name,"argv":["taskset","-c","0-3",candidate["binary"],c["image"],c["request"],"1",dir],"environment":env,"timeout_seconds":600}));steps.push(json!({"kind":"command","name":format!("verify-{name}"),"argv":["/tmp/zopro-gnark-verify/verify","/tmp/zopro-keys",dir.parent().unwrap(),"/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"],"timeout_seconds":120}));jobs.push(json!({"name":name,"directory":dir,"public_sha256":c["public_sha256"]}));}}
 assert_eq!(jobs.len(),18);save(r.join("preflight-jobs.json"),&json!(jobs));save(r.join("preflight-pins.json"),&json!(pins));save(r.join("preflight-plan.json"),&json!({"version":1,"source_pins":r.join("preflight-pins.json"),"steps":steps}));println!("Prepared OFF/ON all9 preflight72SDK18exports;9block all9+physical16; prior12173");}
fn qualify(){let r=Path::new(R);assert_eq!(read(r.join("preflight/result.json"))["status"],"complete");let mut p=read(r.join("perf-before-preflight.json"));let mut seen=prior();let mut inv=BTreeMap::new();let mut pins:BTreeMap<String,String>=serde_json::from_value(p["pins"].clone()).unwrap();for j in read(r.join("preflight-jobs.json")).as_array().unwrap(){let f=Path::new(j["directory"].as_str().unwrap()).join("0.proof");assert_eq!(fs::metadata(&f).unwrap().len(),164);assert_eq!(hash(f.with_extension("public")),j["public_sha256"].as_str().unwrap());assert!(seen.insert(hash(&f)));let dir=r.join("preflight").join(j["name"].as_str().unwrap());let text=fs::read_to_string(dir.join("stdout.log")).unwrap();let summary:Value=serde_json::from_str(text.lines().find_map(|l|l.strip_prefix("SUMMARY ")).unwrap()).unwrap();assert_eq!(summary["rounds"],1);assert_eq!(summary["priming"],3);assert_eq!(summary["workers"],4);let v=fs::read_to_string(r.join("preflight").join(format!("verify-{}",j["name"].as_str().unwrap())).join("stdout.log")).unwrap();assert!(v.contains("verified 1 distinct proofs across 1 pinned keys"));for f in [f.clone(),f.with_extension("public")]{inv.insert(f.display().to_string(),hash(&f));add(f,&mut pins)}}assert_eq!(seen.len(),12191);assert_eq!(inv.len(),36);save(r.join("preflight-proof-inventory.json"),&json!(inv));save(r.join("preflight-analysis.json"),&json!({"passed":true,"SDK_requests":72,"independent_exports":18,"next_prior_count":12191}));for f in ["preflight-plan.json","preflight/result.json","preflight-proof-inventory.json","preflight-analysis.json"]{add(r.join(f),&mut pins)}for(f,h)in &pins{assert_eq!(&hash(f),h)}p["pins"]=json!(pins);p["prior_proof_sha256"]=json!(seen);save(r.join("perf-plan.json"),&p);println!("18preflights verified; prior12191; ready frozen9blocks+6profiles");}
fn main(){match std::env::args().nth(1).as_deref(){Some("prepare")=>prepare(),Some("qualify")=>qualify(),_=>panic!("prepare|qualify")}}
